from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
s=s.replace('    #searchBar::placeholder{color:#78849a;font-weight:500}\n','    #searchBar::placeholder{color:#78849a;font-weight:500}\n    #searchBar::-webkit-search-cancel-button{appearance:none;-webkit-appearance:none;display:none}\n    #searchBar::-webkit-search-decoration{appearance:none;-webkit-appearance:none}\n',1)
s=s.replace('border:1px solid rgba(255,255,255,.42);border-radius:11px;background:#0744ab;color:#fff;font-size:13px;font-weight:800;cursor:pointer;','border:1px solid rgba(255,255,255,.28);border-radius:10px;background:rgba(3,52,146,.84);color:#fff;font-size:13px;font-weight:750;cursor:pointer;',1)
s=s.replace('.header-action:hover{transform:translateY(-2px) scale(1.035);background:#063a92;box-shadow:0 9px 21px rgba(0,30,100,.28),inset 0 1px 0 rgba(255,255,255,.26)}','.header-action:hover{transform:translateY(-2px);background:#063a92;border-color:rgba(255,255,255,.40);box-shadow:0 8px 18px rgba(0,20,75,.23),inset 0 1px 0 rgba(255,255,255,.18)}',1)
s=s.replace('.header-action:active{transform:translateY(1px) scale(.98)}','.header-action:active{transform:translateY(0);box-shadow:0 3px 8px rgba(0,20,75,.18)}',1)
s=s.replace('border:1px solid rgba(255,255,255,.42);border-radius:11px;background:#0744ab;color:#fff;font-size:13px;font-weight:800;cursor:pointer;','border:1px solid rgba(255,255,255,.28);border-radius:10px;background:rgba(3,52,146,.84);color:#fff;font-size:13px;font-weight:750;cursor:pointer;',1)
s=s.replace('.category-toggle:hover{transform:translateY(-2px) scale(1.035);background:#063a92;box-shadow:0 9px 21px rgba(0,30,100,.28),inset 0 1px 0 rgba(255,255,255,.26)}','.category-toggle:hover{transform:translateY(-2px);background:#063a92;border-color:rgba(255,255,255,.40);box-shadow:0 8px 18px rgba(0,20,75,.23),inset 0 1px 0 rgba(255,255,255,.18)}',1)
s=s.replace('.category-toggle:active{transform:translateY(1px) scale(.98)}','.category-toggle:active{transform:translateY(0);box-shadow:0 3px 8px rgba(0,20,75,.18)}',1)
s=s.replace('.search-clear:hover{background:#eef3fb;transform:translateY(-50%) scale(1.05)}','.search-clear:hover{background:#eef2f8;color:#32415c;transform:translateY(-50%) scale(1.04)}\n    .search-clear:active{transform:translateY(-50%) scale(.96)}',1)
p.write_text(s,encoding='utf-8')
